//! Export table of `dlls/msvcr120_app/msvcr120_app.spec`, in spec order.

/// The `-arch=` tokens an entry may carry, as `tools/winebuild/parser.c` (`parse_spec_flags`) reads them.
/// `Win32` and `Win64` are CPU groups (`FLAG_CPU_WIN32` and `FLAG_CPU_WIN64` in
/// `tools/winebuild/build.h`), and `NotI386` is `!i386`, which excludes i386.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Arch {
    Arm,
    Arm64,
    I386,
    NotI386,
    Win32,
    Win64,
    X86_64,
}

impl Arch {
    /// The token as the spec writes it.
    pub fn token(self) -> &'static str {
        match self {
            Arch::Arm => "arm",
            Arch::Arm64 => "arm64",
            Arch::I386 => "i386",
            Arch::NotI386 => "!i386",
            Arch::Win32 => "win32",
            Arch::Win64 => "win64",
            Arch::X86_64 => "x86_64",
        }
    }
}

/// How `msvcr120_app.spec` declares a name.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ExportKind {
    /// Any entry that is not `@ stub`: `cdecl`, `stdcall`, `thiscall`, `varargs` or `extern`. The spec
    /// forwards it to `msvcr120.<name>`, the same name in every case, so this DLL has no code for it.
    Forward,
    /// `@ stub`: calls `__wine_spec_unimplemented_stub`. See [`crate::wine_spec_unimplemented_stub`].
    Stub,
}

/// One line of `msvcr120_app.spec`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Export {
    pub name: &'static str,
    /// The `-arch=` restriction. Empty when the entry applies to every architecture.
    pub arch: &'static [Arch],
    pub kind: ExportKind,
    /// `-private`: winebuild leaves the entry out of the export count (`tools/winebuild/spec32.c`).
    pub private: bool,
}

